package jdk.internal.m3.compression;

import java.io.BufferedInputStream;
import java.io.DataInputStream;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;

/** Replays a bounded corpus generated by independently installed native codecs. */
//FLLDCIM: RELOCATE - donor https://github.com/hsoliwal/com.synexia/blob/6fdee5330b8ab005005785aeff0d1105ba40d12c/synexia-algo/src/test/java/com/synexia/algorithms/compression/M3CompressionInteropSelfTest.java blob fda91c8281ad; recipe m3/compression/recipe/compression-20261106/relocate.py v3
public final class CompressionInteropSelfTest {
    private static final int MAX_RECORDS = 20_000;
    private static final int MAX_BYTES = 2 * 1024 * 1024;

    private CompressionInteropSelfTest() {}

    public static void main(String[] args) throws IOException {
        if (args.length != 1) throw new IllegalArgumentException("expected one corpus path");
        int tested = 0;
        try (DataInputStream source = new DataInputStream(
                new BufferedInputStream(Files.newInputStream(Path.of(args[0]))))) {
            if (source.readInt() != 0x4d33435a) {
                throw new IllegalArgumentException("unsupported M3 compression corpus");
            }
            int count = source.readInt();
            if (count < 1 || count > MAX_RECORDS) {
                throw new IllegalArgumentException("invalid record count");
            }
            for (int i = 0; i < count; i++) {
                int codec = source.readUnsignedByte();
                int plainSize = source.readInt();
                int packedSize = source.readInt();
                if (plainSize < 0 || plainSize > MAX_BYTES || packedSize < 0
                        || packedSize > MAX_BYTES || (codec != 0 && codec != 1)) {
                    throw new IllegalArgumentException("invalid corpus record shape");
                }
                byte[] plain = new byte[plainSize];
                byte[] packed = new byte[packedSize];
                source.readFully(plain);
                source.readFully(packed);
                byte[] decoded = codec == 0
                        ? SnappyRawDecoder.decode(packed, plainSize)
                        : Lz4RawBlockDecoder.decode(packed, plainSize, plainSize);
                if (!Arrays.equals(plain, decoded)) {
                    throw new AssertionError("external codec mismatch at case " + i);
                }
                tested++;
            }
            if (source.read() != -1) throw new IllegalArgumentException("trailing corpus data");
        }
        System.out.println("M3 compression native interop checks=" + tested);
    }
}
